-- Replace imported potion prose with concise, original rules summaries.
-- The Go-side phase then converts formulas, hit-point labels, tables and
-- handbook references into semantic rich-content nodes.
CREATE TEMP TABLE potion_description_seed (
    item_id bigint PRIMARY KEY,
    expected_name text NOT NULL,
    description text NOT NULL
) ON COMMIT DROP;


UPDATE dndshare.item AS item
SET data = jsonb_set(COALESCE(item.data, '{}'::jsonb), '{desc}', to_jsonb(seed.description), true)
FROM potion_description_seed AS seed
WHERE item.id = seed.item_id
  AND item.type_id = 10
  AND item.user_id IS NULL
  AND item.name = seed.expected_name;
