INSERT INTO potion_description_seed (item_id, expected_name, description) VALUES
    (84, 'Зелье лечения', 'Выпив это зелье, существо восстанавливает 2d4 + 2 хита. Красная жидкость мягко светится и мерцает, если встряхнуть флакон.'),
    (99, 'Зелье силы великана', 'Выпив это зелье, вы на 1 час получаете значение Силы, указанное в таблице. Если ваша Сила уже равна ему или выше, зелье не действует. В прозрачной жидкости плавает обломок ногтя великана соответствующего вида. Зелья морозного и каменного великанов дают одинаковую Силу.\n\n| Вид великана | Сила | Редкость |\n|---|---:|---|\n| Холмовой | 21 | Необычное |\n| Морозный или каменный | 23 | Редкое |\n| Огненный | 25 | Редкое |\n| Облачный | 27 | Очень редкое |\n| Штормовой | 29 | Легендарное |'),
    (109, 'Зелье скорости', 'Выпив это зелье, вы на 1 минуту получаете эффект заклинания Ускорение без необходимости поддерживать концентрацию. Жёлтая жидкость сама закручивается во флаконе, а внутри неё тянутся тонкие чёрные прожилки.'),
    (115, 'Зелье силы великана', 'Выпив это зелье, вы на 1 час получаете значение Силы, указанное в таблице. Если ваша Сила уже равна ему или выше, зелье не действует. В прозрачной жидкости плавает обломок ногтя великана соответствующего вида. Зелья морозного и каменного великанов дают одинаковую Силу.\n\n| Вид великана | Сила | Редкость |\n|---|---:|---|\n| Холмовой | 21 | Необычное |\n| Морозный или каменный | 23 | Редкое |\n| Огненный | 25 | Редкое |\n| Облачный | 27 | Очень редкое |\n| Штормовой | 29 | Легендарное |'),
    (120, 'Зелье полёта', 'Выпив это зелье, вы на 1 час получаете скорость полёта, равную вашей скорости ходьбы, и можете парить. Когда эффект заканчивается, находящееся в воздухе существо падает, если ничто другое не удерживает его. Прозрачная жидкость собирается у пробки, а белёсые примеси медленно дрейфуют внутри.'),
    (123, 'Зелье лазания', 'Выпив это зелье, вы на 1 час получаете скорость лазания, равную вашей скорости ходьбы, и совершаете с преимуществом проверки Силы (Атлетика), связанные с лазанием. Коричневый, серебристый и серый слои напоминают каменную породу и не смешиваются даже после встряхивания.'),
    (133, 'Зелье большого лечения', 'Выпив это зелье, существо восстанавливает 4d4 + 4 хита. Красная жидкость мягко светится и мерцает, если встряхнуть флакон.'),
    (143, 'Зелье сопротивления', 'Выпив это зелье, вы на 1 час получаете сопротивление одному виду урона. Вид определяет Мастер самостоятельно или броском по таблице.\n\n| d10 | Вид урона |\n|---:|---|\n| 1 | Кислота |\n| 2 | Холод |\n| 3 | Огонь |\n| 4 | Силовое поле |\n| 5 | Электричество |\n| 6 | Некротическая энергия |\n| 7 | Яд |\n| 8 | Психическая энергия |\n| 9 | Излучение |\n| 10 | Звук |'),
    (163, 'Зелье чтения мыслей', 'Выпив это зелье, вы получаете эффект заклинания Обнаружение мыслей со Сл спасброска 13. В густой фиолетовой жидкости плавает розовое облачко яйцевидной формы.'),
    (167, 'Зелье роста', 'Выпив это зелье, вы на 1d4 часа получаете увеличивающий эффект заклинания Увеличение/уменьшение без необходимости поддерживать концентрацию. Красная капля внутри прозрачной жидкости ритмично разрастается и снова сжимается; встряхивание не нарушает этот цикл.'),
    (183, 'Масло эфирности', 'Маслом можно покрыть существо Среднего размера или меньше вместе с его снаряжением; на каждую категорию размера выше Среднего нужен ещё один флакон. Нанесение занимает 10 минут, после чего существо на 1 час получает эффект заклинания Эфирность. Мутные серые капли выступают снаружи ёмкости и сразу испаряются.'),
    (203, 'Зелье отличного лечения', 'Выпив это зелье, существо восстанавливает 8d4 + 8 хитов. Красная жидкость мягко светится и мерцает, если встряхнуть флакон.'),
    (209, 'Зелье дружбы с животными', 'В течение 1 часа после употребления зелья вы можете неограниченно накладывать заклинание Дружба с животными со Сл спасброска 13. В мутной жидкости кружатся крошечные кусочки чешуи, пера, когтя и шерсти.'),
    (215, 'Зелье превосходного лечения', 'Выпив это зелье, существо восстанавливает 10d4 + 20 хитов. Красная жидкость мягко светится и мерцает, если встряхнуть флакон.'),
    (221, 'Зелье уменьшения', 'Выпив это зелье, вы на 1d4 часа получаете уменьшающий эффект заклинания Увеличение/уменьшение без необходимости поддерживать концентрацию. Красная капля внутри прозрачной жидкости ритмично сжимается и снова разрастается; встряхивание не нарушает этот цикл.'),
    (239, 'Зелье яда', 'На вид, запах и вкус эта смесь неотличима от полезного зелья, но её истинную природу раскрывает заклинание Опознание. Выпив смесь, вы получаете 3d6 урона ядом и должны пройти спасбросок Телосложения Сл 13. При провале вы получаете состояние Отравление и в начале каждого своего хода снова получаете 3d6 урона ядом. В конце каждого хода повторяйте спасбросок: после каждого успеха последующий урон уменьшается на 1d6. Когда урон снижается до 0, действие яда заканчивается.'),
    (248, 'Зелье невидимости', 'Выпив это зелье, вы на 1 час становитесь невидимым. Надетые и переносимые предметы также невидимы, пока остаются при вас. Эффект заканчивается раньше, если вы совершаете атаку или накладываете заклинание. Флакон кажется пустым, хотя внутри ощутимо плещется жидкость.'),
    (285, 'Зелье героизма', 'Выпив это зелье, вы получаете 10 временных очков жизни на 1 час. На то же время на вас действует заклинание Благословение без необходимости поддерживать концентрацию. Синяя жидкость пузырится и дымится, словно кипит.'),
    (294, 'Масло остроты', 'Одной порцией масла можно покрыть одно рубящее или колющее оружие либо до пяти рубящих или колющих боеприпасов. Нанесение занимает 1 минуту. На 1 час покрытый предмет становится магическим и даёт бонус +3 к броскам атаки и урона. В прозрачном желе сверкают мельчайшие серебряные осколки.'),
    (300, 'Зелье газообразной формы', 'Выпив это зелье, вы на 1 час получаете эффект заклинания Газообразная форма без необходимости поддерживать концентрацию. Эффект можно завершить раньше бонусным действием. Внутри флакона клубится туман, который перетекает подобно воде.'),
    (302, 'Зелье силы великана', 'Выпив это зелье, вы на 1 час получаете значение Силы, указанное в таблице. Если ваша Сила уже равна ему или выше, зелье не действует. В прозрачной жидкости плавает обломок ногтя великана соответствующего вида. Зелья морозного и каменного великанов дают одинаковую Силу.\n\n| Вид великана | Сила | Редкость |\n|---|---:|---|\n| Холмовой | 21 | Необычное |\n| Морозный или каменный | 23 | Редкое |\n| Огненный | 25 | Редкое |\n| Облачный | 27 | Очень редкое |\n| Штормовой | 29 | Легендарное |'),
    (311, 'Зелье дыхания под водой', 'Выпив это зелье, вы можете дышать под водой в течение 1 часа. Мутно-зелёная жидкость пахнет морем, а внутри неё плавает похожий на медузу пузырь.'),
    (316, 'Зелье силы великана', 'Выпив это зелье, вы на 1 час получаете значение Силы, указанное в таблице. Если ваша Сила уже равна ему или выше, зелье не действует. В прозрачной жидкости плавает обломок ногтя великана соответствующего вида. Зелья морозного и каменного великанов дают одинаковую Силу.\n\n| Вид великана | Сила | Редкость |\n|---|---:|---|\n| Холмовой | 21 | Необычное |\n| Морозный или каменный | 23 | Редкое |\n| Огненный | 25 | Редкое |\n| Облачный | 27 | Очень редкое |\n| Штормовой | 29 | Легендарное |'),
    (322, 'Зелье ясновидения', 'Выпив это зелье, вы получаете эффект заклинания Подсматривание. В желтоватой жидкости покачивается глазное яблоко, которое исчезает сразу после открытия флакона.'),
    (328, 'Масло скольжения', 'Маслом можно покрыть существо Среднего размера или меньше вместе с его снаряжением; на каждую категорию размера выше Среднего нужен ещё один флакон. Нанесение занимает 10 минут, после чего существо на 8 часов получает эффект заклинания Свобода перемещения. Вместо этого масло можно действием вылить на землю: оно покрывает квадрат 10 × 10 футов и на 8 часов создаёт в этой области эффект заклинания Скольжение со Сл спасброска 13. В ёмкости чёрная мазь кажется густой и тяжёлой, но после выливания растекается мгновенно.'),
    (329, 'Приворотное зелье', 'Первое существо, которое вы увидите в течение 10 минут после употребления зелья, очаровывает вас на 1 час. Если оно принадлежит к виду и полу, которые обычно вас привлекают, на время эффекта вы считаете его своей истинной любовью. В розовой шипучей жидкости прячется маленький пузырёк в форме сердца.');
